using System;using System.IO;using System.IO.Compression;using System.Text;using System.Linq;using System.Collections.Generic;
using Verse;using RimWorld;using PhinixClient.Trade;using Phinix.TradeExtension.Client;using Phinix.LegacyRedPacketExtension.Client;
class Program {
 class Stateless:ThingComp {}
 class Stateful:ThingComp { public int Charge; }
 class SplitBehavior:ThingComp {public override void PostSplitOff(Thing t){} }
 static int passed;
 static void Check(bool ok){if(!ok)throw new Exception("Assertion failed");}
 static void Case(string name,Action test){test();passed++;Console.WriteLine("PASS "+name);}
 static void Throws(Action a){try{a();}catch(InvalidOperationException){return;}throw new Exception("Expected rejection");}
 static byte[] Zip(string xml){using(var o=new MemoryStream()){using(var z=new GZipStream(o,CompressionMode.Compress,true)){var b=Encoding.UTF8.GetBytes(xml);z.Write(b,0,b.Length);}return o.ToArray();}}
 static string Xml(TradeItemSnapshot s){using(var i=new MemoryStream(s.StatePayload))using(var z=new GZipStream(i,CompressionMode.Decompress))using(var r=new StreamReader(z))return r.ReadToEnd();}
 static TradeItemSnapshot Serialize(Thing t)=>new TradeItemSnapshot(t.def.defName,t.stackCount,100,TradeItemQuality.None,null,null,StatefulTradeItemProtocol.ScribeCodecId,Zip("<saveable><def>Steel</def><id>source</id><map>2</map><pos>(1,2,3)</pos><stackCount>"+t.stackCount+"</stackCount>"+t.State+"</saveable>"));
 static readonly ThingDef sharedDefinition=new ThingDef();
 static Thing Thing(int count=75,string state=null){var t=new Thing{stackCount=count,def=sharedDefinition};if(state!=null)t.State=state;return t;}
 static RedPacketSummaryQueue.Notice Notice(string key="packet:completed",string owner="sender")=>new RedPacketSummaryQueue.Notice{Key=key,Owner=owner,Title="Summary",Text="Done"};
 static void Main(){
  Case("realistic medicine subtype and food state do not need a whitelist",()=>{var def=new ThingDef{defName="MedicineHerbal",stackLimit=25};var a=new Medicine{def=def,stackCount=20,State="<rotProgress>0</rotProgress>"};var b=new Medicine{def=def,stackCount=15,State="<rotProgress>5</rotProgress>"};var group=RedPacketStackTemplate.GroupPhysical(new[]{new StackedThings(new Thing[]{a,b})},null,Serialize).Single();Check(RedPacketStackTemplate.PreparePhysical(group,30,Serialize).Template.StackCount==30);def=new ThingDef{defName="MealSimple",stackLimit=10};var c=new ThingWithComps{def=def,stackCount=10,State="<poisonPct>0</poisonPct>"};var d=new ThingWithComps{def=def,stackCount=10,State=c.State};c.AllComps.Add(new FoodState());d.AllComps.Add(new FoodState());Check(RedPacketStackTemplate.GroupPhysical(new[]{new StackedThings(new Thing[]{c,d})},null,Serialize).Single().Things.Count==2);});
  Case("capacity-one gear stays individual even if native quality match allows stacking",()=>{var def=new ThingDef{stackLimit=1};var a=new ThingWithComps{def=def,stackCount=1};var b=new ThingWithComps{def=def,stackCount=1};a.AllComps.Add(new CompQuality{Quality=3});b.AllComps.Add(new CompQuality{Quality=3});Check(a.CanStackWith(b));var groups=RedPacketStackTemplate.GroupPhysical(new[]{new StackedThings(new Thing[]{a,b})},null,Serialize).ToArray();Check(groups.Length==2);Check(RedPacketStackTemplate.PreparePhysical(groups[0],1,Serialize).Template.StackCount==1);Throws(()=>RedPacketStackTemplate.PreparePhysical(new StackedThings(new Thing[]{a,b}),2,Serialize));});
  Case("native veto cannot be bypassed by matching metadata",()=>{var a=Thing();var b=Thing();b.StackAllowed=false;Check(RedPacketStackTemplate.GroupPhysical(new[]{new StackedThings(new[]{a,b})},null,Serialize).Count()==2);Throws(()=>RedPacketStackTemplate.PreparePhysical(new StackedThings(new[]{a,b}),100,Serialize));});
  Case("dominant means total state quantity not largest single pile",()=>{var a=Thing(20,"<state>A</state>");var b=Thing(20,a.State);var c=Thing(35,"<state>B</state>");var group=RedPacketStackTemplate.GroupPhysical(new[]{new StackedThings(new[]{c,a,b})},null,Serialize).Single();var selection=RedPacketStackTemplate.PreparePhysical(group,50,Serialize);Check(selection.Sources.Things.Sum(t=>t.stackCount)==75&&selection.Template.StackCount==50&&Xml(selection.Template).Contains("<state>A</state>"));Check(c.stackCount==35&&c.State.Contains("B")&&a.stackCount==20&&b.stackCount==20);var exact=RedPacketStackTemplate.PreparePhysical(group,30,Serialize);Check(exact.Sources.Things.Count==2&&exact.Sources.Things.All(t=>t.State==a.State));});
  Case("generic aggregation is independent of item definition names",()=>{foreach(string name in new[]{"WoodLog","Steel","Cloth","MedicineHerbal","RawRice","ThirdPartyResource"})foreach(int mode in new[]{0,1,2}){var def=new ThingDef{defName=name};var a=new ThingWithComps{def=def,stackCount=47};var b=new ThingWithComps{def=def,stackCount=75};if(mode==1){a.AllComps.Add(new Stateless());b.AllComps.Add(new Stateless());}if(mode==2){a.AllComps.Add(new CompEquippable());b.AllComps.Add(new CompEquippable());}var groups=RedPacketStackTemplate.GroupPhysical(new[]{new StackedThings(new Thing[]{a,b})},null,Serialize).ToArray();Check(groups.Length==1&&groups[0].Things.Sum(t=>t.stackCount)==122);Check(RedPacketStackTemplate.PreparePhysical(groups[0],100,Serialize).Template.StackCount==100);Check(a.stackCount==47&&b.stackCount==75);}});
  Case("generic grouping never crosses item definition and defers durability to game rules",()=>{var a=new ThingWithComps{def=new ThingDef{defName="Steel"},stackCount=47};var b=new ThingWithComps{def=new ThingDef{defName="Cloth"},stackCount=75};Check(RedPacketStackTemplate.GroupPhysical(new[]{new StackedThings(new Thing[]{a,b})},null,Serialize).Count()==2);b.def=a.def;b.HitPoints=99;Check(RedPacketStackTemplate.GroupPhysical(new[]{new StackedThings(new Thing[]{a,b})},null,Serialize).Count()==1);});
  Case("unused equippable resource stacks aggregate and select across origins",()=>{var a=new ThingWithComps{def=sharedDefinition,stackCount=47};var b=new ThingWithComps{def=sharedDefinition,stackCount=75};a.AllComps.Add(new CompEquippable());b.AllComps.Add(new CompEquippable());var groups=RedPacketStackTemplate.GroupPhysical(new[]{new StackedThings(new Thing[]{a,b})},null,Serialize).ToArray();Check(groups.Length==1&&groups[0].Things.Sum(t=>t.stackCount)==122);var selected=RedPacketStackTemplate.PreparePhysical(groups[0],100,Serialize);Check(selected.Sources.Things.Count==2&&selected.Template.StackCount==100);Check(a.stackCount==47&&b.stackCount==75);});
  Case("native-stackable resources do not use a component whitelist",()=>{var a=new ThingWithComps{def=sharedDefinition};var b=new ThingWithComps{def=sharedDefinition};var comp=new CompEquippable();comp.VerbTracker.Initialize();a.AllComps.Add(comp);b.AllComps.Add(new CompEquippable());Check(RedPacketStackTemplate.GroupPhysical(new[]{new StackedThings(new Thing[]{a,b})},null,Serialize).Count()==1);Throws(()=>RedPacketStackTemplate.Capture(new Thing[]{a,b},150,Serialize));});
  Case("native-stackable state differences remain available for dominant template",()=>{var a=new ThingWithComps{def=sharedDefinition};var b=new ThingWithComps{def=sharedDefinition,State="<health>99</health>"};a.AllComps.Add(new CompEquippable());b.AllComps.Add(new CompEquippable());Check(RedPacketStackTemplate.GroupPhysical(new[]{new StackedThings(new Thing[]{a,b})},null,Serialize).Count()==1);Throws(()=>RedPacketStackTemplate.Capture(new Thing[]{a,b},150,Serialize));});
  Case("public quantity draft rejects invalid and out-of-range input",()=>{foreach(string value in new[]{"", "0", "-1", "101", "2147483648", "1.5", " 1", "+1"})Check(!RedPacketPresentationRules.Quantity(value,100,out _));Check(RedPacketPresentationRules.Quantity("100",100,out int q)&&q==100);});
  Case("packet count follows item quantity and real claim-detail limit",()=>{Check(RedPacketPresentationRules.Packets("3",3,out int n)&&n==3);Check(!RedPacketPresentationRules.Packets("4",3,out _));Check(!RedPacketPresentationRules.Packets("513",1000,out _));Check(RedPacketPresentationRules.Packets("512",1000,out _));});
  Case("claim projection never invents availability",()=>{var now=DateTime.UtcNow;var p=new RedPacket{Id="p",SenderUuid="sender",RemainingCount=10,RemainingPackets=2,ExpiresAtUtc=now.AddMinutes(1)};Check(RedPacketPresentationRules.Claimable(p,"viewer",true,false,now));Check(!RedPacketPresentationRules.Claimable(p,"sender",true,false,now));Check(!RedPacketPresentationRules.Claimable(p,"viewer",false,false,now));Check(!RedPacketPresentationRules.Claimable(p,"viewer",true,true,now));Check(!RedPacketPresentationRules.Claimable(p,"",true,false,now));p.StateRequired=true;p.StateReady=false;Check(!RedPacketPresentationRules.Claimable(p,"viewer",true,false,now));p.StateReady=true;p.ClaimedUuids.Add("viewer");Check(!RedPacketPresentationRules.Claimable(p,"viewer",true,false,now));p.ClaimedUuids.Clear();p.ExpiresAtUtc=now;Check(!RedPacketPresentationRules.Claimable(p,"viewer",true,false,now));});
  Case("200 steel preflight preserves intact state and all original counts",()=>{
   var things=new[]{Thing(),Thing(),Thing()};var plan=RedPacketStackTemplate.PreparePhysical(new StackedThings(things),200,Serialize);
   Check(plan.Sources.Things.Count==3&&plan.Template.StackCount==200);Check(things.All(t=>t.stackCount==75));
   var xml=Xml(plan.Template);Check(xml.Contains("<map>-1</map>")&&xml.Contains("<beenRevealed>true</beenRevealed>")&&xml.Contains("<stackCount>200</stackCount>"));
   // Same failure shape as native SplitOff: the partial entity has its own reveal history.
   var partial=Thing(50,things[2].State.Replace("true","false"));Throws(()=>RedPacketStackTemplate.Capture(new[]{things[0],things[1],partial},200,Serialize));
   Check(Xml(plan.Template).Contains("<beenRevealed>true</beenRevealed>"));
  });
  Case("prefer one sufficient stack",()=>{var a=Thing(50);var b=Thing(250);var p=RedPacketStackTemplate.PreparePhysical(new StackedThings(new[]{a,b}),200,Serialize);Check(p.Sources.Things.Count==1&&ReferenceEquals(p.Sources.Things[0],b)&&b.stackCount==250);});
  Case("source order conserves quantity",()=>{foreach(var counts in new[]{new[]{50,75,100},new[]{100,50,75}}){var ts=counts.Select(c=>Thing(c)).ToArray();Check(RedPacketStackTemplate.PreparePhysical(new StackedThings(ts),200,Serialize).Template.StackCount==200);Check(ts.Select(t=>t.stackCount).SequenceEqual(counts));}});
  Case("authorized dominant template replaces differing state without source mutation",()=>{var a=Thing();var b=Thing(75,a.State.Replace("100","80"));var selected=RedPacketStackTemplate.PreparePhysical(new StackedThings(new[]{a,b}),100,Serialize);Check(selected.Template.StackCount==100&&Xml(selected.Template).Contains("<health>100</health>"));Check(a.stackCount==75&&b.stackCount==75);});
  Case("tick state remains authoritative",()=>{var a=Thing();var b=Thing(75,a.State.Replace("<tickDelta>0","<tickDelta>5"));Throws(()=>RedPacketStackTemplate.Capture(new[]{a,b},150,Serialize));});
  Case("reveal and quest state are not globally ignored",()=>{var a=Thing();var b=Thing(75,a.State+"<questTags><li>quest</li></questTags>");Throws(()=>RedPacketStackTemplate.Capture(new[]{a,b},150,Serialize));});
  Case("equivalent inventory materialization still aggregates",()=>{var ts=new[]{Thing(),Thing()};Check(RedPacketStackTemplate.Capture(ts,150,Serialize).StackCount==150);Check(ts.All(t=>t.stackCount==75));});
  Case("serializer failure restores temporary quantity",()=>{var t=Thing();Throws(()=>RedPacketStackTemplate.CaptureCount(t,200,_=>throw new InvalidOperationException("serializer")));Check(t.stackCount==75);});
  Case("generic stateless components aggregate through grouping and send",()=>{var a=new ThingWithComps{def=sharedDefinition};var b=new ThingWithComps{def=sharedDefinition};a.AllComps.Add(new Stateless());b.AllComps.Add(new Stateless());var groups=RedPacketStackTemplate.GroupPhysical(new[]{new StackedThings(new Thing[]{a,b})},null,Serialize).ToArray();Check(groups.Length==1&&groups[0].Things.Count==2);Check(RedPacketStackTemplate.PreparePhysical(groups[0],100,Serialize).Template.StackCount==100);Check(a.stackCount==75&&b.stackCount==75);});
  Case("strict inventory Capture retains component safety",()=>{foreach(object comp in new object[]{new Stateful(),new SplitBehavior()}){var a=new ThingWithComps{def=sharedDefinition};a.AllComps.Add(comp);var b=new ThingWithComps{def=sharedDefinition};b.AllComps.Add(comp);Throws(()=>RedPacketStackTemplate.Capture(new Thing[]{a,b},150,Serialize));Check(RedPacketStackTemplate.GroupPhysical(new[]{new StackedThings(new Thing[]{a,b})},null,Serialize).Count()==1);}});
  Case("map grouping defers unknown components to game while inventory Capture stays strict",()=>{var a=new ThingWithComps{def=sharedDefinition};a.AllComps.Add(new object());var b=new ThingWithComps{def=sharedDefinition};b.AllComps.Add(new object());Check(RedPacketStackTemplate.Capture(new[]{a},75,Serialize).StackCount==75);Throws(()=>RedPacketStackTemplate.Capture(new Thing[]{a,b},150,Serialize));Check(RedPacketStackTemplate.GroupPhysical(new[]{new StackedThings(new Thing[]{a,b})},null,Serialize).Count()==1);});
  Case("UI native grouping retains a dominant complete-state template",()=>{var a=Thing();var b=Thing();var c=Thing(75,a.State.Replace("100","80"));var groups=RedPacketStackTemplate.GroupPhysical(new[]{new StackedThings(new[]{a,b,c})},null,Serialize).ToArray();Check(groups.Length==1&&groups[0].Things.Count==3);});
  Case("coarse singleton buckets skip all serialization even at large counts",()=>{int calls=0;var items=Enumerable.Range(0,5000).Select(i=>new Thing{def=new ThingDef{defName="def"+i}}).ToArray();var groups=RedPacketStackTemplate.GroupPhysical(new[]{new StackedThings(items)},null,t=>{calls++;return Serialize(t);}).ToArray();Check(groups.Length==5000&&calls==0);Console.WriteLine("FACT coarse-singletons=5000 serialized="+calls);});
  Case("stuff stays separate while HP follows native stackability",()=>{int calls=0;var a=Thing();var b=Thing();b.HitPoints=80;var c=Thing();c.Stuff=new ThingDef{defName="material"};var groups=RedPacketStackTemplate.GroupPhysical(new[]{new StackedThings(new[]{a,b,c})},null,t=>{calls++;return Serialize(t);}).ToArray();Check(groups.Length==2&&calls==2);});
  Case("game quality veto keeps sources separate",()=>{int calls=0;var a=new ThingWithComps{def=sharedDefinition};a.AllComps.Add(new CompQuality{Quality=1});var b=new ThingWithComps{def=sharedDefinition};b.AllComps.Add(new CompQuality{Quality=2});var c=new ThingWithComps{def=sharedDefinition};c.AllComps.Add(new CompColorable());var groups=RedPacketStackTemplate.GroupPhysical(new[]{new StackedThings(new Thing[]{a,b,c})},null,t=>{calls++;return Serialize(t);}).ToArray();Check(groups.Length==3&&calls==3);});
  Case("fingerprint collisions preserve dominant exact-state weighting",()=>{var a=Thing();var b=Thing(75,a.State+"<extra>different</extra>");var c=Thing();var groups=RedPacketStackTemplate.GroupPhysical(new[]{new StackedThings(new[]{a,b,c})},null,Serialize,_=>"collision").ToArray();Check(groups.Length==1);var selection=RedPacketStackTemplate.PreparePhysical(groups[0],175,Serialize);Check(selection.Sources.Things.Count==3&&!Xml(selection.Template).Contains("<extra>"));});
  Case("separate incoming groups share a coarse index without pairwise pregrouping",()=>{int calls=0;var a=Thing();var b=Thing();var groups=RedPacketStackTemplate.GroupPhysical(new[]{new StackedThings(new[]{a}),new StackedThings(new[]{b})},null,t=>{calls++;return Serialize(t);}).ToArray();Check(groups.Length==1&&groups[0].Things.Count==2&&calls==2);});
  Case("inspection budgets never hide excess source stacks",()=>{int calls=0;var items=Enumerable.Range(0,1500).Select(_=>Thing(1)).ToArray();var groups=RedPacketStackTemplate.GroupPhysical(new[]{new StackedThings(items)},null,t=>{calls++;return Serialize(t);}).ToArray();Check(calls==1000&&groups.Sum(g=>g.Things.Count)==1500&&groups.Count(g=>g.Things.Count==1)==500);Console.WriteLine("FACT same-bucket=1500 serialized="+calls+" isolated=500");});
  Case("oversized state inspection is bounded and preserves individual selection",()=>{var a=Thing(75,"<large>"+new string('x',140*1024)+"</large>");var b=Thing(75,a.State);int warnings=0;var groups=RedPacketStackTemplate.GroupPhysical(new[]{new StackedThings(new[]{a,b})},(_,level)=>warnings++,Serialize).ToArray();Check(groups.Length==2&&groups.All(g=>g.Things.Count==1)&&warnings==1);Check(RedPacketStackTemplate.PreparePhysical(groups[0],50,Serialize).Template.StackCount==50);});
  Case("failed oversized inspections consume the shared refresh budget",()=>{var items=Enumerable.Range(0,200).Select(_=>Thing(1,"<large>"+new string('x',140*1024)+"</large>")).ToArray();int calls=0;var groups=RedPacketStackTemplate.GroupPhysical(new[]{new StackedThings(items)},null,t=>{calls++;return Serialize(t);}).ToArray();Check(calls==32&&groups.Sum(g=>g.Things.Count)==200&&groups.All(g=>g.Things.Count==1));});
  Case("send refreshes dominant state without mutating sources",()=>{var a=Thing();var b=Thing();var group=RedPacketStackTemplate.GroupPhysical(new[]{new StackedThings(new[]{a,b})},null,Serialize).Single();b.State+="<changed>true</changed>";Check(RedPacketStackTemplate.PreparePhysical(group,100,Serialize).Template.StackCount==100);Check(a.stackCount==75&&b.stackCount==75);});
  Case("incremental grouping preserves sync output and bounded work steps",()=>{var items=Enumerable.Range(0,50).Select(_=>Thing(1)).ToArray();int calls=0,slices=0,ready=0;using(var job=RedPacketStackTemplate.BeginGrouping(new[]{new StackedThings(items)},null,t=>{calls++;return Serialize(t);})){Throws(()=>{var ignored=job.Results;});while(!job.Completed){int before=calls;job.Advance(1000,3,_=>ready++);Check(calls-before<=3);slices++;}Check(slices>1&&job.Results.Sum(g=>g.Things.Count)==50&&job.Results.Count==1&&ready==1&&calls==50);}});
  Case("cancelling a partial job prevents future serialization and publication",()=>{int calls=0;var items=Enumerable.Range(0,100).Select(_=>Thing(1)).ToArray();var job=RedPacketStackTemplate.BeginGrouping(new[]{new StackedThings(items)},null,t=>{calls++;return Serialize(t);});job.Advance(1000,110);Check(calls>0&&calls<100);job.Dispose();int before=calls;Check(!job.Advance()&&!job.Completed&&calls==before);Throws(()=>{var ignored=job.Results;});job.Dispose();});
  Case("duplicate and insufficient sources reject",()=>{var a=Thing();Throws(()=>RedPacketStackTemplate.PreparePhysical(new StackedThings(new[]{a,a}),100,Serialize));Throws(()=>RedPacketStackTemplate.PreparePhysical(new StackedThings(new[]{a}),100,Serialize));});
  Case("delivery count bounds retained",()=>{Check(RedPacketStackTemplate.DeliveryCounts(200,75).SequenceEqual(new[]{75,75,50}));Throws(()=>RedPacketStackTemplate.DeliveryCounts(1001,1));});
  Case("notification waits for context then delivers once",()=>{var q=new RedPacketSummaryQueue();q.Enqueue(Notice());int n=0;q.Drain("sender",false,_=>n++,null);Check(n==0&&q.Count==1);q.Drain("sender",true,_=>n++,null);q.Enqueue(Notice());q.Drain("sender",true,_=>n++,null);Check(n==1&&q.Count==0);});
  Case("completion and expiry deduplicate independently",()=>{var q=new RedPacketSummaryQueue();q.Enqueue(Notice());q.Enqueue(Notice("packet:expired"));int n=0;q.Drain("sender",true,_=>n++,null);Check(n==2);});
  Case("uncertain letter hook failure never repeats event or letter",()=>{var q=new RedPacketSummaryQueue();q.Enqueue(Notice());int attempted=0,failed=0;q.Drain("sender",true,_=>{attempted++;throw new NullReferenceException();},_=>failed++);q.Enqueue(Notice());q.Drain("sender",true,_=>attempted++,null);Check(attempted==1&&failed==1&&q.Count==0);});
  Case("notification scope reset drops old owner data",()=>{var q=new RedPacketSummaryQueue();q.Enqueue(Notice());q.Drain("another-user",false,_=>throw new Exception(),null);Check(q.Count==0);q.Clear();Check(q.Enqueue(Notice())&&q.Count==1);q.Clear();Check(q.Count==0);});
  Case("notification queue bounded and stores value copies",()=>{var q=new RedPacketSummaryQueue();for(int i=0;i<64;i++)Check(q.Enqueue(Notice(i.ToString())));Check(!q.Enqueue(Notice("overflow")));var value=Notice();q.Clear();q.Enqueue(value);value.Text="changed";q.Drain("sender",true,n=>Check(n.Text=="Done"),null);});
  Console.WriteLine(passed+" repair cases passed (algorithm seams; game acceptance remains required).");
 }
}
